<?php $socialNoun=static function(int $number,array $forms):string{$n=$number%100;return $forms[$n>=11&&$n<=14?2:($n%10===1?0:($n%10>=2&&$n%10<=4?1:2))];}; ?>
<section class="tr-social-page">
    <a class="tr-social-back tr-icon-link" href="<?= htmlSC(base_href('/tape-room/people')) ?>"><?= $this->partial('site-icon',['name'=>'back']) ?><span class="tr-icon-link-label">Все пользователи</span></a>
    <header class="tr-public-profile card"><div class="card-body"><img class="tr-public-avatar" src="<?= htmlSC($person['avatar']) ?>" alt="" width="112" height="112"><div class="tr-public-profile-info"><span class="tr-eyebrow">МУЗЫКАЛЬНЫЙ ПРОФИЛЬ</span><h1><?= htmlSC($person['name']) ?></h1><?php if($person['bio']!==''): ?><p class="tr-public-bio"><?= htmlSC($person['bio']) ?></p><?php endif; ?><?php if(!$person['profilePublic']): ?><p class="tr-public-hidden">Профиль скрыт. Его видите только вы.</p><?php endif; ?><nav class="tr-person-stats" aria-label="Статистика профиля"><a href="<?= htmlSC($person['url']) ?>"><strong><?= $person['albumsCount'] ?></strong> <?= $socialNoun($person['albumsCount'],['альбом','альбома','альбомов']) ?></a><a href="<?= htmlSC($person['url'].'?tab=followers') ?>"><strong data-tr-follow-count="<?= $person['id'] ?>"><?= $person['followersCount'] ?></strong> <span data-tr-follow-noun="<?= $person['id'] ?>"><?= $socialNoun($person['followersCount'],['подписчик','подписчика','подписчиков']) ?></span></a><a href="<?= htmlSC($person['url'].'?tab=following') ?>"><strong><?= $person['followingCount'] ?></strong> <?= $socialNoun($person['followingCount'],['подписка','подписки','подписок']) ?></a></nav></div><div class="tr-public-follow"><?= $this->partial('social-follow',['person'=>$person]) ?></div></div></header>
    <nav class="nav nav-pills tr-social-tabs" aria-label="Музыка и подписки пользователя"><?php foreach(['published'=>'Опубликовано','collection'=>'Коллекция','following'=>'Подписки','followers'=>'Подписчики']as$key=>$label): ?><a class="nav-link <?= $tab===$key?'active':'' ?>" href="<?= htmlSC($person['url'].'?tab='.$key) ?>" <?= $tab===$key?'aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav>
    <?php if(in_array($tab,['following','followers'],true)): ?>
        <?= $this->partial('social-people',['people'=>$social_content['people']]) ?>
    <?php elseif(!empty($social_content['private'])): ?>
        <div class="tr-social-empty"><?= $this->partial('site-icon',['name'=>'shield']) ?><h2>Коллекция закрыта</h2><p>Пользователь пока не открыл свою коллекцию для других.</p></div>
    <?php else: ?>
        <?php if($tab==='collection'&&!$person['collectionPublic']): ?><p class="tr-public-hidden">Эта коллекция видна только вам. Открыть её можно в настройках профиля.</p><?php endif; ?>
        <?php if(!$social_content['albums']): ?><div class="tr-social-empty"><h2><?= $tab==='published'?'Пока нет опубликованных альбомов':'В коллекции пока нет альбомов' ?></h2><p>Здесь появляются только опубликованные и одобренные альбомы.</p></div><?php else: ?>
        <div class="rp-app tr-bootstrap p-0"><div class="rp-album-grid tr-public-albums"><?php foreach($social_content['albums']as$album): ?><article class="rp-album-card"><div class="rp-album-artwork"><a class="rp-album-open" href="<?= htmlSC($album['url']) ?>" aria-label="<?= htmlSC('Открыть альбом '.$album['title']) ?>"><img src="<?= htmlSC($album['cover'] ?: theme_asset_versioned('images/cover-light-320.webp')) ?>" <?php if(!$album['cover']): ?>data-tr-social-cover data-tr-social-cover-light="<?= htmlSC(theme_asset_versioned('images/cover-light-320.webp')) ?>" data-tr-social-cover-dark="<?= htmlSC(theme_asset_versioned('images/cover-dark-320.webp')) ?>"<?php endif; ?> alt="" width="240" height="240" loading="lazy"></a></div><a class="rp-album-title" href="<?= htmlSC($album['url']) ?>"><?= htmlSC($album['title']) ?></a><span class="rp-album-artist"><?= htmlSC($album['artist'] ?: 'Исполнитель не указан') ?></span><small class="rp-album-meta">Треков: <?= $album['tracks'] ?> · <?= gmdate($album['duration']>=3600?'H:i:s':'i:s',(int)$album['duration']) ?></small></article><?php endforeach; ?></div></div>
        <?php endif; ?>
    <?php endif; ?>
    <?= $this->partial('social-pagination',['pagination'=>$social_content,'page_base'=>$person['url'],'page_query'=>['tab'=>$tab]]) ?>
</section>
